import sys
from functools import lru_cache

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            n = int(next(iterator))
        except StopIteration:
            break

        traits = []
        for _ in range(n):
            k = int(next(iterator))
            arr = []
            for _ in range(k):
                arr.append(int(next(iterator)))
            traits.append(arr)

        @lru_cache(maxsize=None)
        def dp(mask, turn):
            total_moves = bin(mask).count('1')
            if total_moves == 0:
                return 0

            max_score = -1

            for i in range(n):
                k = len(traits[i])
                taken_count = 0
                for j in range(k):
                    if mask & (1 << (i * 100 + j)):
                        taken_count += 1

                left_idx = taken_count
                right_idx = k - 1 - (taken_count - (k - taken_count)) if taken_count < k else -1

                if turn == 0:
                    if left_idx < k:
                        bit_pos = i * 100 + left_idx
                        if not (mask & (1 << bit_pos)):
                            new_mask = mask | (1 << bit_pos)
                            score = traits[i][left_idx] + dp(new_mask, 1)
                            if score > max_score:
                                max_score = score
                else:
                    if left_idx < k:
                        bit_pos = i*100 + (k - 1 - (taken_count - (k - taken_count)))
                        if not (mask & (1 << bit_pos)):
                            pass

                    if left_idx < k:
                        available_right = k - 1 - (taken_count - (k - taken_count - 1)) if taken_count < k else -1
                        if taken_count < k:
                            right_idx = k - 1 - (taken_count - (k - (taken_count + 1)))

                    if left_idx < k:
                        right_idx = k - 1 - (taken_count - (k - left_idx - 1))

                    if left_idx < k:
                        right_idx = k - 2 - taken_count + left_idx + 1

                    if left_idx < k:
                        right_idx = k -  - taken_count + left_idx

                    if left_idx < k:
                        right_idx = k - (taken_count - (k - left_idx))

                    if left_idx < k:
                        right_idx = left_idx + (k - taken_count) - 1

                    if left_idx < k and right_idx >= left_idx:
                        bit_pos = i * 100 + right_idx
                        if not (mask & (1 << bit_pos)):
                             new_mask = mask | (1 << bit_pos)
                             score = traits[i][right_idx] + dp(new_mask, 0)
                             if score > max_score:
                                 max_score = score

            return max_score if max_score != -1 else 0

        total_elements = sum(len(t) for t in traits)
        if total_elements == 0:
            results.append("0 0")
            continue

        total_sum = sum(sum(t) for t in traits)

        rk_score = dp(0, 0)
        rg_score = total_sum - rk_score

        results.append(f"{rk_score} {rg_score}")

        dp.cache_clear()

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
